pair[] V;
for(int i=0;i<10;++i) V.push(dir(108-36*i));
fill(V[0]--V[1]--V[2]--V[7]--cycle,gray(0.83));
fill(V[2]--V[3]--V[4]--cycle,gray(0.83));
