Let $P$ be a point inside an isosceles triangle $ABC$ with $AB=AC$. Let $D,E,F$ be the feet of the perpendiculars from $P$ to sides $BC,CA,AB$, respectively. If $BD=9$, $CD=5$, $PE=2$, and $PF=5$, find the length of side $AB$.

Here $XY$ denotes the length of segment $XY$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
pair foot(pair P,pair U,pair V) {
  pair d=V-U;
  return U+((P-U).x*d.x+(P-U).y*d.y)/(abs(d)^2)*d;
}
size(240);
pair A=(7,14),B=(0,0),C=(14,0),P=(9,6),D=(9,0);
pair E=foot(P,C,A),F=foot(P,A,B);
draw(A--B--C--cycle);
draw(P--D,dotted);draw(P--E,dotted);draw(P--F,dotted);
void rightMark(pair X,pair U,pair Y) {
  pair u=0.3*unit(U-X),v=0.3*unit(Y-X);
  draw((X+u)--(X+u+v)--(X+v));
}
rightMark(D,B,P);rightMark(E,A,P);rightMark(F,B,P);
label("A",A,N);label("B",B,SW);label("C",C,SE);
label("D",D,S);label("E",E,NE);label("F",F,NW);label("P",P,NE);
label("9",(B+D)/2,N);label("5",(D+C)/2,N);
label("5",(P+F)/2,S);label("2",(P+E)/2,SE);
[/asy]

